def count_zeros_ones(s):
    """
    统计字符串 s 中 '0' 和 '1' 的个数。

    Args:
        s (str): 输入字符串。

    Returns:
        tuple: 一个元组，包含 (0的个数, 1的个数)。
    """
    count_0 = s.count('0')
    count_1 = s.count('1')
    return count_0, count_1

# --- 示例 ---
input_string = ""

zeros, ones = count_zeros_ones(input_string)

print(f"输入字符串: {input_string}")
print(f"字符 '0' 的个数: {zeros}")
print(f"字符 '1' 的个数: {ones}")

# 如果你想得到总数，可以将两者相加
total_binary_digits = zeros + ones
print(f"字符 '0' 和 '1' 的总个数: {total_binary_digits}")